# Generated by test-lab — blind adversarial evaluation
"""Service integration tests for Docker-based services.

Composes /treesitter violations for AST-based import checks (logging, requests).
File-content checks (Dockerfile, health endpoint, credentials) remain here.

Inputs: target directory path (service root with Dockerfile, server.py, etc.)
Outputs: list of TestCheck results
Failure modes: no Dockerfile found (skip), service not structured
"""
from __future__ import annotations
import os

import json
import subprocess
import sys
from pathlib import Path
from typing import Any

from loguru import logger

_parent = str(Path(__file__).parent.parent)
if _parent not in sys.path:
    sys.path.insert(0, _parent)

from test_lab import TestCheck

# Resolve /treesitter run.sh
_SKILLS_DIR = Path(__file__).resolve().parent.parent.parent
_TREESITTER_RUN = _SKILLS_DIR / "treesitter" / "run.sh"


def _run_treesitter(target_dir: Path) -> list[dict[str, Any]]:
    """Call /treesitter violations for banned imports and return results."""
    cmd = [
        str(_TREESITTER_RUN), "violations", str(target_dir),
        "--rules", "banned-import-logging,banned-import-requests",
        "--json",
    ]
    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=60,
            env={k: v for k, v in os.environ.items() if k != 'VIRTUAL_ENV'},
        )
        if result.stdout.strip():
            return json.loads(result.stdout)
        return []
    except (subprocess.TimeoutExpired, json.JSONDecodeError, OSError) as e:
        logger.warning("treesitter violations unavailable: {}", e)
        return []


def run_checks(target_dir: Path) -> list[TestCheck]:
    """Run service best-practices checks against target directory."""
    checks: list[TestCheck] = []

    dockerfile = target_dir / "Dockerfile"
    server_files = list(target_dir.glob("server.py")) + list(target_dir.glob("app.py"))
    requirements = target_dir / "requirements.txt"
    pyproject = target_dir / "pyproject.toml"

    # Check 1: Dockerfile exists
    checks.append(TestCheck(
        name="dockerfile_exists",
        category="structure",
        passed=dockerfile.exists(),
        description="Service must have a Dockerfile",
    ))

    if not dockerfile.exists():
        return checks  # Can't check more without Dockerfile

    # Check 2: Dockerfile health
    df_content = dockerfile.read_text(encoding="utf-8", errors="ignore")

    checks.append(TestCheck(
        name="dockerfile_expose",
        category="structure",
        passed="EXPOSE" in df_content,
        description="Dockerfile must EXPOSE a port",
    ))

    checks.append(TestCheck(
        name="dockerfile_user",
        category="security",
        passed="USER" in df_content and "root" not in df_content.split("USER")[-1].split("\n")[0].lower(),
        description="Dockerfile should not run as root",
    ))

    checks.append(TestCheck(
        name="dockerfile_cmd",
        category="structure",
        passed="CMD" in df_content or "ENTRYPOINT" in df_content,
        description="Dockerfile must have CMD or ENTRYPOINT",
    ))

    # Check 3: Server file exists and has health endpoint
    if server_files:
        server_path = server_files[0]
        server_content = server_path.read_text(encoding="utf-8", errors="ignore")

        checks.append(TestCheck(
            name="health_endpoint",
            category="conventions",
            passed="/health" in server_content,
            description="Service must have /health endpoint",
        ))

        checks.append(TestCheck(
            name="error_handling",
            category="correctness",
            passed="HTTPException" in server_content or "raise" in server_content,
            description="Service must have error handling (HTTPException or similar)",
        ))

        # AST-based checks via /treesitter violations (banned imports)
        violations = _run_treesitter(target_dir)
        violated_rules = {v.get("rule") for v in violations}

        checks.append(TestCheck(
            name="use_loguru",
            category="conventions",
            passed="banned-import-logging" not in violated_rules,
            description="Service must use loguru, not import logging"
            if "banned-import-logging" in violated_rules
            else "Correctly uses loguru",
        ))

        checks.append(TestCheck(
            name="use_httpx",
            category="conventions",
            passed="banned-import-requests" not in violated_rules,
            description="Service must use httpx, not import requests"
            if "banned-import-requests" in violated_rules
            else "Correctly uses httpx",
        ))
    else:
        checks.append(TestCheck(
            name="server_exists",
            category="structure",
            passed=False,
            description="Service must have server.py or app.py",
        ))

    # Check 4: Dependencies
    has_deps = requirements.exists() or pyproject.exists()
    checks.append(TestCheck(
        name="dependencies_defined",
        category="structure",
        passed=has_deps,
        description="Service must declare dependencies (requirements.txt or pyproject.toml)",
    ))

    # Check 5: run.sh entry point
    run_sh = target_dir / "run.sh"
    if run_sh.exists():
        run_content = run_sh.read_text(encoding="utf-8", errors="ignore")
        checks.append(TestCheck(
            name="run_sh_docker",
            category="conventions",
            passed="docker" in run_content.lower(),
            description="run.sh should manage Docker lifecycle (build/start/stop)",
        ))

    # Check 6: No hardcoded credentials
    all_py = list(target_dir.glob("*.py"))
    has_hardcoded_creds = False
    for py_file in all_py:
        try:
            content = py_file.read_text(encoding="utf-8", errors="ignore")
            if any(pattern in content for pattern in [
                "password=", "api_key=", "secret=", "token=",
            ]):
                # Exclude if reading from env
                lines_with_cred = [
                    line for line in content.splitlines()
                    if any(p in line for p in ["password=", "api_key=", "secret=", "token="])
                    and "os.environ" not in line and "getenv" not in line
                    and not line.strip().startswith("#")
                    and "=" in line.split("#")[0]  # not in comment
                ]
                if lines_with_cred:
                    has_hardcoded_creds = True
                    break
        except Exception:
            continue

    checks.append(TestCheck(
        name="no_hardcoded_credentials",
        category="security",
        passed=not has_hardcoded_creds,
        description="Service must not hardcode credentials — use environment variables",
    ))

    return checks
